 t=time.monotonic();p=subprocess.Popen(argv,cwd=repo,env=env,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
 timed=False
 try:a,b=p.communicate(inp,timeout=timeout)
 except subprocess.TimeoutExpired:
  timed=True;os.killpg(p.pid,signal.SIGTERM)
  try:a,b=p.communicate(timeout=2)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);a,b=p.communicate()
 (out/(name+'.stdout')).write_bytes(a);(out/(name+'.stderr')).write_bytes(b)
 row={'name':name,'argv':argv,'exit_code':p.returncode,'timed_out':timed,'wall_seconds':time.monotonic()-t,'diagnostic_no_lazy_fetch':offline,'stdout_bytes':len(a),'stdout_sha256':hashlib.sha256(a).hexdigest(),'stderr_bytes':len(b),'stderr_sha256':hashlib.sha256(b).hexdigest()};records.append(row)
 return p.returncode,a,b,timed
