 rc,a,_,to=run('candidate-commit-status',['git','cat-file','--batch-check=%(objectname) %(objecttype) %(objectsize)'],inp=(report['candidate']+'\n').encode(),offline=True);report['candidate_commit_local']=a.decode().strip();report['candidate_check_timed_out']=to
 rc,a,_,to=run('index-flags',['git','ls-files','-v','--',payload['path']],offline=True);report['index_flags']=a.decode().strip()
 rc,refs_after,_,to=run('refs-after',['git','for-each-ref','--format=%(refname) %(objectname)'],offline=True);assert rc==0 and not to and refs_after==refs;report['refs_unchanged']=True
